// SPANISH — machine-assisted, written against the rules below and validated mechanically.
//
// Covers all 4681 keys in the English source.
//
// PARTIAL BY DESIGN — and that property is what made it safe to land this in two waves rather
// than one enormous drop. Any key absent here resolves to the English source string at runtime
// (`rawMessage` falls through), so a gap is a español screen with an English sentence in it —
// never a blank, never a raw key.
//
// ⚠️ WHAT IS NOT TRANSLATED, AND MUST NOT BE: frequencies and every number that is one, signal
// reports, callsigns, grid squares, band and mode names, Q-codes, RST/RR73/CQ/73, POTA and SOTA
// references, ADIF field names, service names (LoTW, eQSL, ClubLog, N1MM, WSJT-X, Hamlib,
// rigctld, OmniRig, FlexRadio), the control vocabulary (CAT, PTT, ALC, ATU, AGC, RIT, XIT),
// units, and product names.
//
// ⚠️ THE DECIMAL COMMA IS THE DANGEROUS ONE. Español writes una coma decimal where English
// writes a point, and a dial, a log line or a CAT setting reading 14,074 is an operating fault
// rather than a cosmetic one. Two things hold that line: `invariantNumber` is `String(n)`, so no
// interpolated number can pick up a locale separator; and `placeholders.test.ts` fails CI on any
// value here that introduces a comma-between-digits the English does not have. That guard was
// German-only until this catalog landed — see its own note.
//
// ⚠️ {{placeholders}} are verbatim. A reordered sentence is fine; a renamed token fails CI.
//
// Validated on generation: no key added or dropped against the English source, no placeholder
// mismatch, no protected token translated, and NO NUMBER ALTERED — digit for digit, separator
// for separator.
//
// Register and terminology come from an 80-term glossary agreed before any translating began,
// so the parallel passes could not each invent their own word for the same control. What no
// machine check can confirm is whether a español-speaking operator would RECOGNISE the wording;
// that wants a native pass, and the fallback above makes fixing it incremental.
