  "assist.why.arrl": "En los concursos de la <b>ARRL</b> se llama asistencia de spots y se nombran “PSKReporter, Telnet, webs de spots de DX o sistemas de tablón de anuncios, decodificadores multicanal automáticos”. Single Operator no puede usarla (HCAT.1.1: “no se permite el uso de asistencia de spots”). <b>Single Operator Unlimited</b> sí (HCAT.2.1). El glosario de la ARRL define un decodificador multicanal como el software que “muestra varias señales decodificadas a la vez”. Nexus decodifica una señal cada vez, así que esa definición no describe su decodificador de CW. Sí describe los feeds de cluster, RBN y PSK Reporter.",
