  "assist.why.cqww": "La regla VIII.2 de <b>CQ WW</b> cuenta como asistencia para encontrar QSOs “un decodificador de CW, DX cluster, webs de spots de DX … tecnología local o remota de decodificación de indicativos y frecuencias (p. ej., CW Skimmer o Reverse Beacon Network)”. Usar cualquiera de ellos lleva la participación a <b>Single Operator Assisted</b> (V.A.2) en vez de Single Operator (V.A.1).",
  "assist.why.notCovered": "<b>Lo que este interruptor no cubre:</b> los spots de activadores de POTA y SOTA siguen llegando. Ninguna de las dos reglamentaciones nombra esos feeds, pero las dos definen la asistencia de forma lo bastante amplia como para incluirlos, así que desactiva a mano las funciones de POTA/SOTA si participas en un concurso que las cuente.",
  "assist.why.ownDecodes": "Las <b>decodificaciones de tu propio equipo</b> no son asistencia en ninguna de las dos reglamentaciones, así que siguen alimentando el panel de Necesarios en modo sin asistencia. Tus subidas a PSK Reporter también siguen funcionando, porque la ARRL dice que “generar información de spots para que la usen otras estaciones no se considera asistencia de spots”.",
