  "sat.log.note": "Anota un contacto normal desde tu dial, exactamente igual que los paneles de log de Fonía y CW. <b>No</b> se marca como QSO por satélite: Nexus todavía no escribe los campos ADIF PROP_MODE y SAT_NAME, así que el contacto no cuenta ni para el crédito de satélite de LoTW <b>ni para los totales de satélite del propio Nexus</b>. Añade tú <b>los dos</b> campos si quieres ese crédito — uno sin el otro se rechaza al firmar, y en 2 m el locator contaría si no para tu VUCC terrestre, que un contacto por satélite no da.",
  "sat.log.note.title": "Anota un contacto normal desde tu dial, exactamente igual que los paneles de log de Fonía y CW. NO se marca como QSO por satélite: Nexus todavía no escribe los campos ADIF PROP_MODE y SAT_NAME, así que el contacto no cuenta ni para el crédito de satélite de LoTW ni para los totales de satélite del propio Nexus. Añade tú LOS DOS campos si quieres ese crédito — uno sin el otro se rechaza al firmar, y en 2 m el locator contaría si no para tu VUCC terrestre, que un contacto por satélite no da.",
