  "settings.countryFile.empty": "Archivo de países integrado activo.",
  "settings.countryFile.pending": "Actualización descargada (AD1C {{ver}}) — se aplica en el próximo arranque.",
  "settings.countryFile.hint": "El archivo de países cty.dat de AD1C asigna indicativos a entidades DXCC — el país en las filas decodificadas, el panel Needed y el log. Se comprueba semanalmente; una actualización descargada se aplica en el próximo arranque.",
  "settings.callsignState.legend": "Base de datos indicativo → estado",
