  "settings.confirmations.cloudlog.apiKey.forget.title": "Quitar la clave de Cloudlog guardada del llavero del sistema",
  "settings.confirmations.cloudlog.apiKey.hint": "Cloudlog ▸ Account ▸ API Keys — una clave con lectura/escritura. Se guarda en el llavero del sistema, nunca en disco.",
  "settings.confirmations.cloudlog.apiKey.label": "API key",
  "settings.confirmations.cloudlog.apiKey.placeholder": "la API key de tu instancia",
  "settings.confirmations.cloudlog.note": "Reenvía automáticamente cada QSO anotado a tu logbook <b>Cloudlog</b> o <b>Wavelog</b> autoalojado (HTTP). La API key es un token por instancia de tu propio servidor — introdúcela, pon el id de tu perfil de estación y activa el interruptor.",
  "settings.confirmations.cloudlog.stationId.hint": "El perfil de ubicación de estación contra el que anotar (Cloudlog ▸ Station Locations).",
