  "settings.confirmations.clublog.password.forget.title": "Quitar la contraseña de ClubLog guardada del llavero del sistema",
  "settings.confirmations.clublog.password.hint": "Usa una <b>Application Password</b> de ClubLog (Settings → App Passwords), no tu contraseña principal. Se guarda en el llavero del sistema.",
