  "settings.confirmations.eqsl.sync.label": "Confirmaciones de eQSL",
  "settings.confirmations.eqsl.upload.hint": "Sube cada QSO a eQSL.cc según lo anotas (necesita el usuario y la contraseña de eQSL de arriba).",
  "settings.confirmations.eqsl.upload.label": "Subir QSOs a eQSL automáticamente",
