  "settings.contestCategory.unassisted.hint": "Desactiva a la vez el decodificador de CW con IA, los spots de DX cluster / RBN y el feed de necesarios de PSK Reporter, y registra el cambio con fecha y hora. Efecto inmediato. Tus ajustes de cada uno de ellos no se tocan y vuelven al desactivar esto.",
  "settings.contestCategory.unassisted.label": "Participación sin asistencia",
  "settings.cw.idAfter73.hint": "Manipula tu indicativo en CW en cuanto el 73 final ha salido del aire por completo (opción de serie de WSJT-X, desactivada por defecto). Usa la ruta normal de manipulación en CW — PTT + tono — después del turno de FT8, nunca encima.",
  "settings.cw.idAfter73.label": "ID en CW tras el 73",
  "settings.cw.keyLine.dtr": "DTR (la convención en CW)",
  "settings.cw.keyLine.hint": "Qué línea de control manipula el equipo. DTR es lo estándar (RTS = PTT); cambia a RTS si tu interfaz está cableada al revés.",
  "settings.cw.keyLine.label": "Línea de manipulación",
  "settings.cw.keyPort.hint": "El USB-serie hacia tu interfaz de manipulación (Buxcomm, un cable DTR casero, …) que se conecta al jack KEY del equipo. Debe ser un puerto SEPARADO del CAT. Pon el equipo en CW y su jack de manipulación en straight-key / bug. Una interfaz con un chip WinKey dentro — Timewave Navigator, microHAM, un K1EL WinKeyer — <b>no</b> manipula por DTR: elige arriba el backend WinKeyer y dale el puerto CW de ese dispositivo.",
  "settings.cw.keyPort.label": "Puerto serie de manipulación",
  "settings.cw.keyPort.placeholder": "{{example}} — la interfaz de manipulación (distinta del CAT)",
  "settings.cw.keyer.cat": "CAT — el equipo manipula el CW (Hamlib send_morse; solo equipos modernos)",
  "settings.cw.keyer.hint": "Cómo envía CW Nexus. <b>CAT</b> usa el manipulador interno del equipo, pero los equipos antiguos (p. ej. IC-756PRO III) no lo admiten. <b>Línea serie</b> conmuta DTR/RTS hacia el jack KEY del equipo (equipo en CW, el equipo conforma la señal — el método limpio de N1MM/fldigi, solo necesita un cable de manipulación). <b>WinKeyer</b> gobierna un K1EL.<b>Tarjeta de sonido</b> manipula un tono de audio — un apaño; ajusta la excitación para que el ALC marque cero. <b>Saca el equipo de CW</b> y lo pasa a un modo de datos (DATA-U/DATA-L, para que el tono llegue al transmisor y no al jack de micrófono); elige cualquier otro manipulador y el modo CW vuelve enseguida. También se puede cambiar en vivo desde el cockpit de CW.",
  "settings.cw.keyer.label": "Backend del manipulador",
  "settings.cw.keyer.serial": "Línea serie (DTR/RTS) — manipula el jack KEY del equipo",
  "settings.cw.keyer.soundcard": "Tarjeta de sonido — tono de audio por un modo de datos (apaño)",
  "settings.cw.keyer.unproven": "La manipulación de CW por CAT <b>no está comprobada en este equipo</b>. Su backend de Hamlib envía una orden de manipulación distinta de la que se usa en otros equipos, e informa de éxito en cualquier caso — así que si no sale nada al aire, Nexus no puede avisarte. Si el CW no sale, usa la línea serie, el WinKeyer o la tarjeta de sonido.",
  "settings.cw.keyer.title": "Manipulador",
  "settings.cw.keyer.winkeyer": "WinKeyer — manipulador hardware K1EL",
  "settings.cw.legend": "CW",
  "settings.cw.macros.builtin.hint": "Se usa el conjunto F1–F8 integrado. Personalízalo para hacerlo tuyo (etiquetas + plantillas; tokens: {MYCALL} {RST} {NAME} y ! = el indicativo trabajado).",
  "settings.cw.macros.customize": "Personalizar",
