  "settings.cw.macros.role.report": "Enviar reporte",
  "settings.cw.macros.role.signOff": "Despedida (73)",
  "settings.cw.macros.row.label.aria": "Etiqueta de {{key}}",
  "settings.cw.macros.row.text.aria": "Texto de {{key}}",
  "settings.cw.macros.title": "Macros (perfiles de teclas F)",
  "settings.cw.macros.tokens.hint": "Tokens: {MYCALL} {NAME} {MYGRID} {MYSTATE} {RST} · ! = el indicativo trabajado · {HISNAME} {HISSTATE} = nombre/estado en QRZ de la estación trabajada (rellena Ajustes ▸ Estación para {MYSTATE}; el resto se completan solos desde el copiloto / clic en Estaciones + consulta QRZ). Cada tecla CONSERVA su papel — el resaltado del siguiente paso del copiloto Guiado sigue al papel, así que el texto personalizado avanza igual por F1→F2→F3→F4. Mantén el token ! donde quieras que se inserte el indicativo de la otra estación. Guardar para aplicar.",
  "settings.cw.pitch.hint": "Frecuencia del tono de CW (300–1200 Hz) — el tono del manipulador por tarjeta de sonido y el marcador de batido cero del scope de CW.",
  "settings.cw.pitch.label": "Tono lateral (Hz)",
  "settings.cw.winkeyerPort.hint": "El puerto serie que presenta tu WinKey. 1200 baudios. Un WinKey micro dentro de una interfaz multifunción (Timewave Navigator, microHAM) cuenta — usa el puerto CW/WinKey de ese dispositivo, no su puerto CAT.",
  "settings.cw.winkeyerPort.label": "Puerto del WinKeyer",
