  "settings.fieldDay.category.hint": "Transmisores + ubicación: H=Home, I=Indoor, M=Mobile, O=Outdoor (ej. 2O = 2 transmisores, exterior).",
  "settings.fieldDay.category.label": "Categoría WFD",
  "settings.fieldDay.class.hint": "Número de transmisores + letra de clase: A=portable de club/grupo, B=portable de 1–2 personas, C=móvil, D=casa (red eléctrica), E=casa (alimentación de emergencia), F=EOC. Ej. 3A = 3 transmisores, club portable.",
  "settings.fieldDay.class.label": "Clase FD",
  "settings.fieldDay.event.aria": "Evento de Field Day",
  "settings.fieldDay.event.hint": "En qué evento operas: afecta a las etiquetas de puntuación y a las cabeceras de exportación.",
  "settings.fieldDay.event.label": "Evento",
