  "settings.fieldDay.mode.hint": "Actívalo para el fin de semana de Field Day: muestra el espacio de trabajo de Field Day y el intercambio Clase/Sección en todos los modos. Desactivado el resto del año. Rellena Clase + Sección abajo para empezar a operar. Guardar para aplicar.",
  "settings.fieldDay.mode.label": "Modo Field Day",
