  "settings.fieldDay.section.hint": "Tu sección ARRL / RAC (ej. WI, ENY, ONN). Empieza a escribir el código o el nombre de un estado y elige de la lista — validado contra las {{count}} secciones. Necesario para el log Cabrillo.",
  "settings.fieldDay.section.invalid": "“{{section}}” no es una sección ARRL/RAC conocida — elige una de la lista.",
  "settings.fieldDay.section.label": "Sección ARRL",
  "settings.fst4.hint": "<b>FST4</b> es el modo de QSO; <b>FST4W</b> es el modo baliza tipo WSPR — elige cuál en el selector de nivel. Nexus decodifica ambos y no transmite ninguno. Ten en cuenta que los indicativos con hash de FST4W se muestran como <code><...></code>: la tabla de consulta original se rellena desde un archivo que esta build no incluye.",
  "settings.fst4.legend": "FST4 (QSO) / FST4W (baliza)",
  "settings.fst4.period.deepest": "1800 s — el más profundo",
  "settings.fst4.period.hint": "Compartido por ambos niveles. Los periodos largos oyen señales más débiles a costa de menos intercambios por hora. Las balizas FST4W van a 120/300/900/1800 s; el trabajo de QSO en FST4 suele ser de 15–60 s. Ambas estaciones (o la baliza que escuchas) deben estar en el mismo periodo.",
  "settings.fst4.period.label": "Periodo T/R",
  "settings.fst4.period.shortestBeacon": "120 s — intervalo de baliza FST4W más corto",
  "settings.headphoneMonitor.device.hint": "Tus auriculares o altavoces — NO puede ser el dispositivo de salida TX del equipo.",
  "settings.headphoneMonitor.device.label": "Auriculares o altavoces",
  "settings.headphoneMonitor.enable.aria": "Reproducir el audio de recepción en este ordenador",
  "settings.headphoneMonitor.enable.hint": "Reproduce el audio RECIBIDO — exactamente lo que oye el decodificador — por un dispositivo de este ordenador, para diagnosticar niveles y RFI o simplemente para escuchar la banda. No es un monitor de transmisión: nunca reproduce tu propia voz. Desactivado por defecto; SIN VERIFICAR en el aire hasta la sesión atendida.",
  "settings.headphoneMonitor.enable.label": "Reproducir el audio de recepción aquí",
