  "settings.integrations.saveWav.decodes": "Guardar los periodos con decodificaciones",
  "settings.integrations.saveWav.hint": "Los WAV van a recordings/periods (12 kHz mono, ~360 KB cada uno). \"Todos\" escribe ~2 GB/día de escucha continua — para depurar el decodificador, no para dejarlo siempre activo.",
  "settings.integrations.saveWav.label": "Guardar el audio recibido (.wav por periodo)",
