  "settings.integrations.wsjtxUdp.hint": "para JTAlert / GridTracker / loggers",
  "settings.jt65.hint": "El clásico modo de señal débil y rebote lunar, se decodifica y se transmite. Los mensajes usan el formato antiguo de 22 caracteres, no el de 37 que usan FT8 y compañía.",
  "settings.jt65.legend": "JT65 — EME clásico",
  "settings.jt65.submode.a": "A — estándar en HF, el más estrecho",
  "settings.jt65.submode.b": "B — separación 2x",
  "settings.jt65.submode.c": "C — separación 4x, el más tolerante al Doppler",
  "settings.jt65.submode.hint": "JT65 usa siempre un periodo T/R de 60\\u00a0s, así que la separación es lo único que se elige. A es lo que quieres en HF; los operadores de EME suben a B o C cuando la dispersión Doppler de las bandas altas emborrona los tonos. Ambas estaciones deben usar el mismo submodo.",
  "settings.jt65.submode.label": "Submodo (separación de tonos)",
  "settings.lotwUsers.empty": "Aún sin descargar — las listas de decodificaciones marcan con una L los indicativos que suben a LoTW.",
  "settings.lotwUsers.fetch.action": "Descargar ahora",
  "settings.lotwUsers.fetch.busy": "Descargando…",
  "settings.lotwUsers.fetch.done": "Lista de LoTW cargada — {{count}} indicativos",
  "settings.lotwUsers.fetch.failed": "Falló la descarga de la lista de LoTW: {{detail}}",
  "settings.lotwUsers.legend": "Lista de usuarios de LoTW",
  "settings.lotwUsers.maxAge.hint": "La lista de actividad de la ARRL se actualiza cada semana — volver a descargarla más a menudo solo devuelve \"sin cambios\". Descarga manual a propósito (convención de WSJT-X).",
  "settings.lotwUsers.maxAge.label": "Contar como usuario de LoTW si ha subido en (días)",
  "settings.lotwUsers.status": "{{count}} indicativos · descargada {{date}}",
  "settings.msk144.hint": "MSK144 transmite casi todo el periodo, mandando cientos de veces la misma trama de 72 ms — así funciona el meteor scatter, y un contacto puede llevar muchos minutos de aparente silencio. La frecuencia de audio está fija en un centro de 1500 Hz; la señal ocupa 1 kHz, así que no hay dónde sintonizarla. Los mensajes abreviados (MSK40) están desactivados, igual que por defecto en WSJT-X.",
  "settings.msk144.legend": "MSK144 — meteor scatter",
  "settings.msk144.period.fast": "5 s — turnos rápidos, lluvias grandes",
  "settings.msk144.period.hint": "MSK144 manda un mensaje de 72\\u00a0ms una y otra vez, así que una sola estela de meteoro de una décima de segundo puede llevarlo entero. Los periodos cortos aceleran el intercambio durante una lluvia; los largos dan al decodificador más tramas que apilar cuando los pings son escasos. Las dos estaciones deben usar el mismo periodo.",
  "settings.msk144.period.label": "Periodo T/R",
  "settings.msk144.period.sparse": "30 s — pings escasos, más que apilar",
  "settings.msk144.period.standard": "15 s — el estándar en 6 m",
  "settings.n1mm.addr.hint": "Adónde van los paquetes de contacto de N1MM (host:puerto, UDP). Pon el puerto — los consumidores se apilan en un mismo host, y el 12060 suele estar ya ocupado por otro programa de log. Déjalo vacío para desactivarlo.",
  "settings.n1mm.addr.idle": "Una dirección sola no manda nada fuera de un evento de Field Day — activa abajo Difundir todos los QSOs para el log del día a día.",
  "settings.n1mm.addr.label": "Dirección de difusión de contactos de N1MM",
  "settings.n1mm.addr.placeholder": "{{example}} (vacío = off)",
  "settings.n1mm.addr.sending": "Se manda en cada QSO anotado.",
  "settings.n1mm.broadcastAll.hint": "Manda el paquete de contacto de <b>todos</b> los QSOs anotados, no solo los de Field Day — apunta OpenHamClock o GridTracker a la dirección de arriba y cada contacto se dibuja en su mapa según lo anotas. Un paquete por QSO: esto nunca se duplica con la difusión de Field Day, así que se puede dejar activado durante todo el evento. Desactivado por defecto; con esto apagado, los paquetes salen <em>solo</em> mientras hay un evento de Field Day en marcha.",
  "settings.n1mm.broadcastAll.label": "Difundir todos los QSOs",
  "settings.n1mm.legend": "Integración con N1MM+",
  "settings.n3fjp.forwardAll.hint": "Manda además <b>todos</b> los QSOs anotados (no solo los de Field Day) a N3FJP ACLog en el host de arriba — log general del día a día. N3FJP quita duplicados, así que es seguro usarlo junto al envío de Field Day.",
  "settings.n3fjp.forwardAll.label": "Reenviar todos los QSOs",
  "settings.n3fjp.host.hint": "IP o nombre del ordenador con el log maestro. Déjalo vacío para desactivarlo.",
  "settings.n3fjp.host.label": "Host de N3FJP",
  "settings.n3fjp.host.placeholder": "{{example}} (vacío = off)",
  "settings.n3fjp.legend": "Integración con N3FJP (log maestro del club)",
  "settings.n3fjp.note": "Cada contacto de FD entra en el <b>N3FJP Field Day Contest Log</b> del club en cuanto lo anotas — así la puntuación de todo el club se actualiza en tiempo real. Ejecuta N3FJP en el ordenador maestro; apunta Nexus a su IP + puerto (por defecto 1100).",
  "settings.n3fjp.port.hint": "Puerto TCP de la API de N3FJP (por defecto 1100).",
  "settings.n3fjp.port.label": "Puerto de N3FJP",
  "settings.n3fjp.reportBand.hint": "Dile a N3FJP en qué banda estás (sin necesidad de CAT), para que el panel de bandas del Network Status Display del club muestre este puesto. Desactivado por defecto.",
  "settings.n3fjp.reportBand.label": "Informar de mi banda a N3FJP",
  "settings.n3fjp.test.action": "Probar N3FJP",
  "settings.n3fjp.test.hint": "Ejecuta esto en el sitio del club antes de que empiece el evento para confirmar que el enlace con la API funciona.",
  "settings.n3fjp.test.label": "Prueba de conexión",
  "settings.n3fjp.test.title": "Guardar los ajustes y luego probar la conexión TCP con N3FJP",
  "settings.n3fjp.useEnter.hint": "Anota cada contacto de FD con la secuencia <b>ENTER</b> de N3FJP, que es la que puntúa el concurso — la vía correcta. Desactívalo para caer en una inserción <code>ADDDIRECT</code> simple (puede no puntuar). Activado por defecto.",
  "settings.n3fjp.useEnter.label": "Usar ENTER para puntuar en Field Day",
  "settings.orbitalElements.hint": "Elementos keplerianos (TLE) de los satélites de radioaficionado — las horas de pasada, el apuntamiento y el Doppler salen de ellos. Se refrescan cada 6 h desde hamradiotools.io: la lista de satélites viene de la base de datos SatNOGS (CC BY-SA 4.0) y los elementos de CelesTrak y SatNOGS. Importa un archivo para un shack sin conexión o un satélite recién lanzado.",
  "settings.orbitalElements.import.action": "Importar de archivo",
