  "settings.orbitalElements.import.title": "Importa un archivo de elementos descargado (TLE de Celestrak, keps de AMSAT, el juego SupGP de un lanzamiento nuevo) — la salida de emergencia para el shack sin conexión. Las importaciones se mantienen entre refrescos; gana el epoch más nuevo de cada satélite.",
