  "settings.profiles.load.action": "Cargar",
  "settings.profiles.load.title": "Aplica este perfil — se fusiona con tus ajustes actuales. El indicativo, la clase de licencia, la lista de equipos y el historial de sincronización nunca vienen de un perfil, y todo lo que el perfil no conozca mantiene su valor actual.",
