  "settings.psk.legend": "PSK",
  "settings.psk.rxAutoArm.hint": "La pantalla de PSK arranca el decodificador nada más abrirla — pulsa una traza en la cascada y el texto sale impreso, sin preparar nada. Desactiva esto para armar el receptor a mano (el botón Armar RX en el panel de texto decodificado). Si paras tú el receptor, eso ya se recuerda durante el resto de la sesión. Esto arma solo el RECEPTOR — nunca se arma la transmisión por ti.",
  "settings.psk.rxAutoArm.label": "Empezar a recibir al abrir PSK",
  "settings.q65.hint": "Q65 transmite y recibe. El periodo y el submodo fijan lo que oyes y lo que mandas, y LAS DOS ESTACIONES DEBEN COINCIDIR — un corresponsal con otro periodo u otro submodo no te decodificará.",
  "settings.q65.legend": "Q65 — EME / scatter en VHF+",
  "settings.q65.period.deepEme": "120 s — EME profundo",
  "settings.q65.period.eme": "60 s — EME (lo más común)",
  "settings.q65.period.hint": "Los periodos largos integran más tiempo y oyen señales más débiles, a un intercambio por periodo. Las dos estaciones deben usar el <b>mismo</b> periodo. Cambiar esto cambia la longitud de la trama de decodificación, así que surte efecto en el siguiente slot.",
  "settings.q65.period.label": "Periodo T/R",
  "settings.q65.period.meteor": "30 s — meteoros en 6 m / ionoscatter",
  "settings.q65.period.microwaveEme": "300 s — lo más profundo, EME en microondas",
