  "settings.q65.submode.d": "D — separación x8",
  "settings.q65.submode.e": "E — separación x16, la más tolerante al Doppler",
  "settings.q65.submode.hint": "Más separación aguanta más dispersión Doppler y deriva de frecuencia, pero cuesta sensibilidad. Sube de letra según se degrada el camino — el EME en las bandas altas suele necesitar B o C.",
  "settings.q65.submode.label": "Submodo (separación de tonos)",
