  "setup.finish.packs.sub": "Opcional — un conjunto ya hecho de frecuencias y redes habituales, añadido a tus Memorias. Se pueden cambiar o quitar luego en la sección Memorias.",
  "setup.finish.packs.title": "¿Empezar con algunos canales?",
  "setup.finish.sub": "Todos los modos y todas las secciones vienen ACTIVADOS — FT8/FT4, Fonía, CW, RTTY, SSTV, APRS, satélites, los mapas, todo. Nexus es un solo programa en vez de seis; no hay nada que desbloquear. Si algún día quieres una app más ligera, recorta secciones en Ajustes.",
