  "setup.log.sources": "De WSJT-X, N1MM, Log4OM, HRD, QRZ, LoTW, ClubLog — cualquier exportación ADIF estándar (.adi/.adif). Nada sale de tu ordenador; los duplicados se detectan y se omiten.",
  "setup.log.sub": "Nexus funciona mejor cuando conoce tu historial. Importar tu log ADIF es lo que activa las marcas de <b>trabajado antes</b>, el panel <b>Necesarios</b> (nuevos DXCC / estados / locators) y tu progreso de <b>diplomas</b> — sin él, la app empieza a ciegas y trata cada estación como nueva. Es opcional y se puede importar en cualquier momento desde el Log, pero es lo que más útil hace la app desde el primer día.",
